(function(){
 let lang='fr';const q=new URLSearchParams(location.search).get('lang');
 try{lang=q||localStorage.getItem('ia_lang')||'fr';if(q)localStorage.setItem('ia_lang',q)}catch(e){lang=q||'fr'}
 if(lang!=='en')lang='fr';document.documentElement.lang=lang;
 const tg=document.createElement('div');tg.className='lang';tg.innerHTML='<button type="button" data-l="fr"'+(lang==='fr'?' class="on"':'')+'>FR</button><button type="button" data-l="en"'+(lang==='en'?' class="on"':'')+'>EN</button>';
 const hr=document.querySelector('.hr');if(hr)hr.prepend(tg);
 const mt=tg.cloneNode(true);mt.classList.add('lm');const mm=document.getElementById('menu');if(mm)mm.appendChild(mt);
 document.addEventListener('click',e=>{const b=e.target.closest('.lang button');if(!b)return;try{localStorage.setItem('ia_lang',b.dataset.l)}catch(x){}const u=new URL(location.href);u.searchParams.delete('lang');location.href=u.toString()});
 if(lang!=='en')return;
 window.I18N_T=s=>I18N[s.trim()]||s;
 const tr=s=>{const t=s.trim();return t&&I18N[t]!==undefined?s.replace(t,I18N[t]):null};
 const run=root=>{const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){const r=tr(n.nodeValue);if(r!==null&&r!==n.nodeValue)n.nodeValue=r}
  (root.querySelectorAll?root:document).querySelectorAll('[placeholder],[alt],[aria-label],[title]').forEach(el=>['placeholder','alt','aria-label','title'].forEach(a=>{const v=el.getAttribute(a);if(v){const r=tr(v);if(r!==null)el.setAttribute(a,r)}}));
  (root.querySelectorAll?root:document).querySelectorAll('input[readonly]').forEach(el=>{const r=tr(el.value);if(r!==null)el.value=r})};
 const go=()=>{run(document.body);const r=tr(document.title);if(r)document.title=r};
 go();new MutationObserver(ms=>ms.forEach(m=>{if(m.type==='characterData'){const r=tr(m.target.nodeValue);if(r!==null&&r!==m.target.nodeValue)m.target.nodeValue=r}else m.addedNodes.forEach(nd=>{if(nd.nodeType===3){const r=tr(nd.nodeValue);if(r!==null&&r!==nd.nodeValue)nd.nodeValue=r}else if(nd.nodeType===1)run(nd)})})).observe(document.body,{childList:true,subtree:true,characterData:true});
})();
